    def select_end_points_manmidlines(self):
        if not hasattr(self, "original_image") or self.original_image is None:
            error("No original image found.")
            return

        from PyQt5.QtWidgets import (
            QDialog, QVBoxLayout, QHBoxLayout, QPushButton,
            QSizePolicy, QApplication, QMessageBox, QScrollArea, QLabel
        )

        boxes = self.get_all_bounding_boxes()

        # --- Separate "read-only" midlines & connections from editable ones ---
        readonly_midlines = {}
        readonly_connections = []
        existing_midlines = {}

        if "annotations" in self.annotation:
            ann = self.annotation["annotations"]

            # Existing manual midlines (global coords) → store for bbox conversion
            ann_midlines = ann.get("midlines", {})
            for k_str, pts in ann_midlines.items():
                try:
                    i1, i2 = map(int, k_str.split("_"))
                    existing_midlines[(min(i1, i2), max(i1, i2))] = [tuple(map(float, xy)) for xy in pts]
                except:
                    pass

            # Existing auto connections (from atomic cracks) — global coords
            for crack in ann.get("atomic_cracks", {}).values():
                if crack.get("source") == "auto":
                    ml = crack.get("midline", [])
                    if len(ml) >= 2:
                        p1, p2 = tuple(ml[0]), tuple(ml[-1])
                        readonly_connections.append((p1, p2))

        # --- Ensure all endpoints exist in initial points ---
        initial_points = list(getattr(self, "user_points", []) or [])
        point_index_map = {tuple(pt): idx for idx, pt in enumerate(initial_points)}

        def ensure_point(pt):
            if tuple(pt) not in point_index_map:
                point_index_map[tuple(pt)] = len(initial_points)
                initial_points.append(pt)
            return point_index_map[tuple(pt)]
        
        # --- Fill read-only midlines (keep in full-image coords) ---
        for (i1, i2), poly in existing_midlines.items():
            start_idx = ensure_point(poly[0])
            end_idx = ensure_point(poly[-1])
            readonly_midlines[(start_idx, end_idx)] = poly

        # --- Fill read-only connections (keep in full-image coords) ---
        readonly_conn_idx = []
        for p1, p2 in readonly_connections:
            idx1 = ensure_point(p1)
            idx2 = ensure_point(p2)
            readonly_conn_idx.append((min(idx1, idx2), max(idx1, idx2)))

        print(readonly_connections, readonly_conn_idx)

        initial_conns = list(getattr(self, "user_connections", []) or [])

        annot = CrackAnnotator(
            image=self.original_image,
            boxes=boxes,
            initial_points=initial_points,
            initial_connections=initial_conns,
            initial_midlines={},  # start fresh editable set
        )

        # Attach read-only sets to annotator
        annot.readonly_midlines = readonly_midlines
        annot.readonly_connections = readonly_conn_idx

        annot.setSizePolicy(QtWidgets.QSizePolicy.Ignored, QtWidgets.QSizePolicy.Ignored)

        dlg = QDialog(self.MainWindow)
        dlg.setWindowTitle("Endpoints, Connections & Manual Midlines")
        dlg.setWindowModality(Qt.ApplicationModal)
        dlg.setWindowFlags(dlg.windowFlags() | Qt.WindowMaximizeButtonHint)
        layout = QVBoxLayout(dlg)

        mode_btn = QPushButton("Switch to Connection Mode")
        mode_btn.setCheckable(True)
        layout.addWidget(mode_btn)

        manual_btn = QPushButton("Manual Midlines: OFF")
        manual_btn.setCheckable(True)
        manual_btn.setVisible(False)
        layout.addWidget(manual_btn)

        hint = QLabel(
            "Manual: Left-hold on starting point → draw (hold/click) → finish w/ hold/click endpoint.\n"
            "Read-only cracks shown in gray — can't be deleted."
        )
        layout.addWidget(hint)

        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setWidget(annot)
        layout.addWidget(scroll, 1)

        btn_row = QHBoxLayout()
        btn_done, btn_cancel = QPushButton("Done"), QPushButton("Cancel")
        btn_row.addWidget(btn_done)
        btn_row.addWidget(btn_cancel)
        layout.addLayout(btn_row)

        def all_points_in_boxes():
            def in_any(pt):
                x, y = pt
                for xmin, ymin, xmax, ymax in boxes:
                    if xmin <= x <= xmax and ymin <= y <= ymax:
                        return True
                return False

            # Build set of point indices from read-only items
            readonly_point_idxs = set()
            for (i1, i2) in annot.readonly_connections:
                readonly_point_idxs.update([i1, i2])
            for (i1, i2) in annot.readonly_midlines.keys():
                readonly_point_idxs.update([i1, i2])

            # Only check points that are NOT in readonly sets
            bad = [
                pt for idx, pt in enumerate(annot.points)
                if idx not in readonly_point_idxs and not in_any(pt)
            ]
            return (len(bad) == 0, bad)

        def confirm_discard():
            mb = QMessageBox(dlg)
            mb.setIcon(QMessageBox.Warning)
            mb.setWindowTitle("Discard current midline?")
            mb.setText("You're in the middle of drawing a midline. Discard it?")
            mb.setStandardButtons(QMessageBox.Yes | QMessageBox.No)
            return mb.exec_() == QMessageBox.Yes

        def update_controls_visibility():
            if annot.polyline_mode:
                mode_btn.setVisible(False)
                manual_btn.setVisible(True)
                manual_btn.setText("Manual Midlines: ON")
                manual_btn.setStyleSheet("background:#79d2e6;")
            else:
                mode_btn.setVisible(True)
                if annot.connection_mode:
                    mode_btn.setText("Switch to Point Mode")
                    mode_btn.setStyleSheet("background:#97e297;")
                else:
                    mode_btn.setText("Switch to Connection Mode")
                    mode_btn.setStyleSheet("background:#e2c297;")
                manual_btn.setVisible(annot.connection_mode and (not annot.all_pairs_saturated()))
                manual_btn.setText("Manual Midlines: OFF")
                manual_btn.setStyleSheet("")

        mode_btn.clicked.connect(lambda: (annot.toggle_mode(), update_controls_visibility()))
        manual_btn.clicked.connect(lambda checked: (
            annot.set_mode_polyline(checked, confirm_cb=confirm_discard),
            update_controls_visibility()
        ))
        update_controls_visibility()

        def on_done():
            if annot.polyline_mode and annot._is_drawing:
                if not confirm_discard():
                    return
                annot.set_mode_polyline(False)

            ok, bad = all_points_in_boxes()
            if not ok:
                QMessageBox.warning(dlg, "Points outside boxes", "All points must be inside a bounding box.")
                return

            self.user_points = annot.points
            self.all_selected_points = list(self.user_points)  # keep permanent copy for matching later
            self.user_connections = [c for c in annot.connections if c not in annot.readonly_connections]

            self.endpoint_pairs = [
                (self.user_points[i1], self.user_points[i2])
                for (i1, i2) in self.user_connections
            ]

            self.manual_endpoint_pairs = []
            for (i1, i2), poly in annot.midlines.items():
                self.manual_endpoint_pairs.append((self.user_points[i1], self.user_points[i2]))

            self.manual_midlines_tmp = {
                f"{i1}_{i2}": [[float(x), float(y)] for (x, y) in poly]
                for (i1, i2), poly in annot.midlines.items()
            }

            
            print("\n[DEBUG] --- Saving manual midlines from annotator ---")
            print(f"[DEBUG] Annotator midlines count: {len(annot.midlines)}")
            for key, poly in annot.midlines.items():
                print(f"[DEBUG] Key: {key}, FirstPt: {poly[0] if poly else None}, LastPt: {poly[-1] if poly else None}")
            print(f"[DEBUG] Annotator points: {annot.points}")
            print(f"[DEBUG] Annotator connections: {annot.connections}")

            self.manual_midlines_tmp = {
                f"{i1}_{i2}": [[float(x), float(y)] for (x, y) in poly]
                for (i1, i2), poly in annot.midlines.items()
            }

            print(f"[DEBUG] Stored manual_midlines_tmp keys: {list(self.manual_midlines_tmp.keys())}")
            for k, v in self.manual_midlines_tmp.items():
                print(f"[DEBUG]   {k}: first={v[0]}, last={v[-1]}")

            dlg.accept()

        btn_done.clicked.connect(on_done)
        btn_cancel.clicked.connect(lambda: dlg.reject())

        dlg.showMaximized()
        QApplication.processEvents()
        if dlg.exec_() != QDialog.Accepted:
            return

        print(f"Points: {self.user_points}")
        print(f"Connections: {self.user_connections}")
        print(f"Endpoint pairs: {self.endpoint_pairs}")
        print(f"Manual endpoint pairs: {getattr(self, 'manual_endpoint_pairs', [])}")
        print(f"Midlines saved: {len(self.manual_midlines_tmp)}")
        self.update_image_crop_button.setStyleSheet("background-color: lightblue")
         
    def update_image_crop(self):
        try:
            downsample_factor = self.downsample_factor_box.value()
            color_channel = [0 if self.color_chenel_box.currentText()=='R' else 1 if self.color_chenel_box.currentText()=='B' else 2]

            # Use only the bounding box for cropping!
            if not (hasattr(self, "active_bbox") and self.active_bbox is not None):
                raise ValueError("No active bounding box for cropping.")
            xmin, ymin, xmax, ymax = [int(round(v)) for v in self.active_bbox]
            # Sanity check
            if xmax <= xmin or ymax <= ymin:
                print(f"Invalid bounding box cropping window: ({xmin},{ymin}) to ({xmax},{ymax}), skipping.")
                return

            # Crop the image to the bounding box
            self.image_crop = self.original_image[ymin:ymax, xmin:xmax]
            # Ensure the crop is not too small for tracking/segmentation
            h, w = self.image_crop.shape[:2]
            if h < min_crop_size or w < min_crop_size:
                print(f"Skipping segment: Crop too small for processing ({w}x{h})")
                # Optionally set a flag to skip the rest of the pipeline for this segment
                self.skip_current_segment = True
                return
            else:
                self.skip_current_segment = False
            # Shift endpoints relative to bbox origin
            self.pts_crop = [np.array([pt[0]-xmin, pt[1]-ymin]) for pt in self.pts]

            # Sanity check: make sure all shifted points are in bounds
            img_h, img_w = self.image_crop.shape[:2]
            for pt in self.pts_crop:
                if not (0 <= pt[0] < img_w and 0 <= pt[1] < img_h):
                    print(f"Endpoint {pt} not in bbox-cropped image ({img_w},{img_h}), skipping this segment.")
                    return

            # Downsample as before
            black_crack = [0 if self.crack_color_box.currentText() =='Bright crack' else 1 ][0]
            func = np.min if black_crack==1 else np.max
            self.image_crop_down = skimage.measure.block_reduce(
                self.image_crop, block_size=(downsample_factor, downsample_factor, 1),
                func=func, cval=0, func_kwargs=None)
            self.pts_crop_down = [np.array(x) / downsample_factor for x in self.pts_crop]
            self.image_down = skimage.measure.block_reduce(
                self.original_image, block_size=(downsample_factor, downsample_factor, 1),
                func=func, cval=0, func_kwargs=None)
            self.pts_down = [np.array(x) / downsample_factor for x in self.pts]
            gs_image = self.image_crop_down[:,:,color_channel].astype(np.uint8)
            h, w = gs_image.shape[:2]
            for idx, pt in enumerate(self.pts_crop_down):
                x, y = int(round(pt[0])), int(round(pt[1]))
                if 0 <= x < w and 0 <= y < h:
                    gs_image = cv2.circle(gs_image, center=(x, y), radius=2, color=(0,255,0), thickness=2)
                else:
                    print(f"Warning: Skipping drawing point ({x},{y}) out of image bounds ({w},{h})")
            qimage = QImage(gs_image.astype(dtype=np.uint8), gs_image.shape[1], gs_image.shape[0],
                            gs_image.strides[0], QImage.Format_Grayscale8)
            pixmap = QPixmap.fromImage(qimage)
            scaled_pixmap = pixmap.scaled(self.image_crop_down_display.width(), self.image_crop_down_display.height(), Qt.KeepAspectRatio, Qt.FastTransformation)
            self.image_crop_down_display.setPixmap(scaled_pixmap)
            self.x_size_show.display(self.image_crop_down.shape[1])
            self.y_size_show.display(self.image_crop_down.shape[0])
            self.update_os_button.setStyleSheet("background-color : lightblue")
            
            # Debug: Visualize crop and points
        except Exception as e:
            import traceback
            traceback.print_exc()
            error(f"update_image_crop: {e}")
            self.update_os_button.setStyleSheet("background-color : red")

    def check_wavelet(self):
        try:
            size = self.wavelet_size_box.value()
            nOrientations = self.wavelet_norientations_box.value()
            design = "N"
            inflectionPoint = self.wavelet_inflection_point_box.value()
            mnOrder = self.wavelet_mnorder_box.value()
            splineOrder = 3
            overlapFactor = self.wavelet_overlap_factor_box.value()
            dcStdDev = self.wavelet_STD_box.value()
            directional = False
            window_size = self.wavelet_window_size_box.value()

            wavelet = ct.os.CheckWavelet(window_size = window_size, size = size, nOrientations = nOrientations, design = design, 
                            inflectionPoint = inflectionPoint, mnOrder = mnOrder, splineOrder = splineOrder,
                            overlapFactor = overlapFactor, dcStdDev = dcStdDev, directional = directional,
                            display_orientations=[0])[0,:,:]
            wavelet = wavelet - np.min(wavelet)
            wavelet = (wavelet*254/np.max(wavelet)).astype(dtype=np.int8)

            qimage = QImage(wavelet.astype(dtype=np.uint8), wavelet.shape[1], wavelet.shape[0], 
                            wavelet.strides[0], QImage.Format_Grayscale8)
            pixmap = QPixmap.fromImage(qimage)
            scaled_pixmap = pixmap.scaled(self.wavelet_check_display.width(), self.wavelet_check_display.height(), Qt.KeepAspectRatio, Qt.FastTransformation)
            self.wavelet_check_display.setPixmap(scaled_pixmap)
        except Exception as e:
            error(e)

    def update_os(self):
        try:
            self.os_progress_bar.setValue(0)
            color_channel = [0 if self.color_chenel_box.currentText()=='R' else 1 if self.color_chenel_box.currentText()=='B' else 2][0]
            black_crack = -1 if self.crack_color_box.currentText() =='Bright crack' else 1
            size = self.wavelet_size_box.value()
            nOrientations = self.wavelet_norientations_box.value()
            design = "N"
            inflectionPoint = self.wavelet_inflection_point_box.value()
            mnOrder = self.wavelet_mnorder_box.value()
            splineOrder = 3
            overlapFactor = self.wavelet_overlap_factor_box.value()
            dcStdDev = self.wavelet_STD_box.value()
            directional = False
            from time import time
            start_time = time()

            # --- Use the full downsampled image for OS ---
            img_full = self.image_crop_down[:,:,color_channel].copy()  # shape (H_full, W_full)

            # --- Compute the orientation score on the full downsampled image ---
            os_results = ct.os.OrientationScoreTransform(
                img_full / 255 * black_crack, size=size, nOrientations=nOrientations,
                design=design, inflectionPoint=inflectionPoint, mnOrder=mnOrder,
                splineOrder=splineOrder, overlapFactor=overlapFactor,
                dcStdDev=dcStdDev, directional=directional
            )
            '''mask_bin = (self.current_mask > 0)
            xmin, ymin, xmax, ymax = [int(round(v)) for v in self.active_bbox]
            mask_cropped = mask_bin[ymin:ymax, xmin:xmax]
            mask3d = np.broadcast_to(mask_cropped, os_results.shape)
            os_results = np.where(mask3d, os_results, 0)'''
            self.osGFCost = os_results

            print(f"OrientationScoreTransform time: {time() - start_time}")
            self.os_progress_bar.setValue(100)
            self.update_cost_button.setStyleSheet("background-color : lightblue")
            self.show_os_button.setStyleSheet("background-color : lightblue")
        except Exception as e:
            error(e)
            self.update_cost_button.setStyleSheet("background-color : red")
            self.show_os_button.setStyleSheet("background-color : red")
    
    def update_cost(self):
        try:
            self.update_cost_bar.setValue(0)
            lambdaa = self.lambda_box.value()
            p = self.power_box.value()
            ksi = 1
            zeta = 1
            sigmas = self.sigmas_line_edit.text()
            sigmas = [float(i) for i in sigmas.split(sep = ',')]
            sigmas_ext = 1
            start_time = time.time()
            self.multiscalecostLIFExtReg = ct.os.MultiScaleVesselness(self.osGFCost.real,ksi,1,sigmas,"LIF",sigmas_ext = sigmas_ext)
            print(f"MultiScaleVesselness took {time.time() - start_time:.2f} seconds")
            
            start_time = time.time()
            costmultiscale = ct.os.MultiScaleVesselnessFilter(self.multiscalecostLIFExtReg)
            print(f"MultiScaleVesselnessFilter took {time.time() - start_time:.2f} seconds")
            start_time = time.time()
            self.costFunction = ct.os.CostFunction(costmultiscale,lambdaa = lambdaa, p = p)
            print(f"CostFunction took {time.time() - start_time:.2f} seconds")

            if getattr(self, 'current_mask', None) is not None and self.current_mask is not None:
                # Sharpen cost inside mask
                improved_cost = self.costFunction ** 2.0  # (You can tune the exponent as needed)
                # If mask exists, apply it to the cost function
                mask_bin = (self.current_mask > 0)
                xmin, ymin, xmax, ymax = [int(round(v)) for v in self.active_bbox]
                mask_cropped = mask_bin[ymin:ymax, xmin:xmax]
                mask3d = np.broadcast_to(mask_cropped, self.costFunction.shape)
                PENALTY = 5.0
                improved_cost = np.where(mask3d, improved_cost, np.clip(improved_cost * PENALTY, 0, 1))
                self.costFunction = improved_cost
            c00 = np.min(ct.os.Rescale(self.costFunction),axis = 0)
            #c00 = np.max(ct.os.Rescale(self.costFunction), axis=0)
            self.update_cost_bar.setValue(100)
            c00 = c00 - np.min(c00)
            c00 = (c00*255/np.max(c00)).astype(dtype=np.uint8)
            print("c00 shape:", c00.shape)
            qimage = QImage(c00.astype(dtype=np.uint8), c00.shape[1], c00.shape[0], 
                            c00.strides[0], QImage.Format_Grayscale8)
            pixmap = QPixmap.fromImage(qimage)
            scaled_pixmap = pixmap.scaled(self.cost_display.width(), self.cost_display.height(), Qt.KeepAspectRatio, Qt.FastTransformation)
            self.cost_display.setPixmap(scaled_pixmap)
            print("c00 shape:", c00.shape)
            self.midline_track_button.setStyleSheet("background-color : lightblue")
        except Exception as e:
            error(e)
            self.midline_track_button.setStyleSheet("background-color : red")

    def midline_tracking(self):
        try :
            self.tracking_bar.setValue(0)
            w = self.track_width_box.value()
            if self.track_color_box.currentText() == "R":
                color = (255,0,0)
            elif self.track_color_box.currentText() == "G":
                color = (0,255,0)
            elif self.track_color_box.currentText() == "B":
                color = (0,0,255)
            elif self.track_color_box.currentText() == "W":
                color = (255,255,255)

            y_margin = self.y_margin_box.value()
            x_margin = self.x_margin_box.value()
            g11 = self.g11_box.value()
            g22 = self.g22_box.value()
            g33 = self.g33_box.value()
            x_margin = self.x_margin_box.value()
            downsample_factor = self.downsample_factor_box.value()

            track_crop_down = ct.tracking.fast_marching(self.costFunction,self.pts_crop_down[0],self.pts_crop_down[1],g11=g11,g22=g22,g33=g33)
            track_crop_down[0] = track_crop_down[0]-0.5
            track_crop_down[1] = track_crop_down[1]-0.5
            track_crop = track_crop_down.copy()
            track_crop[0] = track_crop_down[0]*downsample_factor
            track_crop[1] = track_crop_down[1]*downsample_factor
            self.track_crop = track_crop
            track = ct.tools.track_crop_to_full(track_crop,self.pts[0],self.pts[1],y_margin,x_margin)
            #print(self.track_crop, track,downsample_factor)
            self.track = track
            #print(self.track)
            pts = np.array(track_crop).transpose(1,0).reshape((-1,1,2)).astype(np.int32)
            im = self.image_crop.astype(np.uint8)
            im = cv2.polylines(im, [pts], False, color, w)
            #print("...")
            qimage = QImage(im, im.shape[1], im.shape[0], 
                            im.strides[0], QImage.Format_RGB888)
            pixmap = QPixmap.fromImage(qimage)
            scaled_pixmap = pixmap.scaled(self.track_display.width(), self.track_display.height(), Qt.KeepAspectRatio, Qt.FastTransformation)
            self.track_display.setPixmap(scaled_pixmap)
            self.tracking_bar.setValue(100)
            self.update_track_display_button.setStyleSheet("background-color : lightblue")
            self.track_full_screen_button.setStyleSheet("background-color : lightblue")
            self.edge_mask_button.setStyleSheet("background-color : lightblue")
        except Exception as e:
            error(e)
            self.update_track_display_button.setStyleSheet("background-color : red")
            self.track_full_screen_button.setStyleSheet("background-color : red")
            self.edge_mask_button.setStyleSheet("background-color : red")
                
    def edge_mask(self):
        try:
            window_half_size = int(self.edge_filter_size_box.value() / 2)
            black_crack = [-1 if self.crack_color_box.currentText() == 'Bright crack' else 1][0]
            color_channel = [0 if self.color_chenel_box.currentText() == 'R'
                            else 1 if self.color_chenel_box.currentText() == 'B'
                            else 2][0]

            print(f"[EDGE_MASK] window_half_size={window_half_size}, black_crack={black_crack}, color_channel={color_channel}")
            print(f"[EDGE_MASK] self.track shape={np.array(self.track).shape}, sample={np.array(self.track)[:, :5]}")
            print(f"[EDGE_MASK] self.pts={self.pts}, active_bbox={self.active_bbox}, current_source={getattr(self, 'current_source', None)}")

            img_gray = self.original_image[:, :, color_channel] * black_crack
            track = np.array(self.track)

            # Always store as [y, x] in full image coordinates
            if getattr(self, "current_source", None) in ("manual", "manual_poly"):
                # Manual track was stored in crop coords → convert back to full image coords
                xmin, ymin, xmax, ymax = [int(round(v)) for v in self.active_bbox]
                track_full_y = track[0] + ymin
                track_full_x = track[1] + xmin
                track = np.vstack([track_full_y, track_full_x])
                print("[EDGE_MASK] Manual mode - converted crop coords to full image coords")
            else:
                # Auto mode: stored as [y, x] but needs swap + shift
                track = np.vstack([track[1], track[0]])
                target_point = np.array([self.pts[1][1], self.pts[1][0]])
                shift_vector = target_point - track[:, 0]
                track = track + shift_vector[:, np.newaxis]
                print(f"[EDGE_MASK] Auto mode - applied shift: {shift_vector}")

            xmin, ymin, xmax, ymax = [int(round(v)) for v in self.active_bbox]
            self.edge_mask1, self.edge_mask2 = ct.segmentation.edge_masks(img_gray, track)

            print(f"[EDGE_MASK] edge_mask1 stats: min={self.edge_mask1.min()}, max={self.edge_mask1.max()}, shape={self.edge_mask1.shape}")
            print(f"[EDGE_MASK] edge_mask2 stats: min={self.edge_mask2.min()}, max={self.edge_mask2.max()}, shape={self.edge_mask2.shape}")

            # Crop masks
            self.edge_mask1_crop = self.edge_mask1[ymin:ymax, xmin:xmax]
            self.edge_mask2_crop = self.edge_mask2[ymin:ymax, xmin:xmax]
            print(f"[EDGE_MASK] Cropped masks: shape1={self.edge_mask1_crop.shape}, shape2={self.edge_mask2_crop.shape}")

            # Adjust track to crop coordinates
            shifted_track = np.zeros_like(track)
            shifted_track[0] = track[0] - ymin
            shifted_track[1] = track[1] - xmin
            self.adjusted_track = shifted_track
            print(f"[EDGE_MASK] adjusted_track sample={self.adjusted_track[:, :5]}")

            # Normalize for display
            edge_mask1_crop = self.edge_mask1_crop - np.min(self.edge_mask1_crop)
            if np.max(edge_mask1_crop) != 0:
                edge_mask1_crop = (edge_mask1_crop * 255 / np.max(edge_mask1_crop)).astype(dtype=np.uint8)
            else:
                edge_mask1_crop = (edge_mask1_crop * 255).astype(dtype=np.uint8)

            qimage = QImage(edge_mask1_crop, edge_mask1_crop.shape[1], edge_mask1_crop.shape[0],
                            edge_mask1_crop.strides[0], QImage.Format_Grayscale8)
            pixmap = QPixmap.fromImage(qimage)
            scaled_pixmap = pixmap.scaled(self.edge_map_display.width(), self.edge_map_display.height(), Qt.KeepAspectRatio, Qt.FastTransformation)
            self.edge_map_display.setPixmap(scaled_pixmap)
            self.edge_tracks_button.setStyleSheet("background-color : lightblue")
        except Exception as e:
            import traceback
            traceback.print_exc()
            error(e)
            self.edge_tracks_button.setStyleSheet("background-color : red")
        
    def edge_tracks_full_screen(self):
        try:
            w = self.edge_track_width_box.value()
            if self.edge_track_color_box.currentText() == "R":
                c = 'r'
            elif self.edge_track_color_box.currentText() == "G":
                c = 'g'
            elif self.edge_track_color_box.currentText() == "B":
                c = 'b'
            elif self.edge_track_color_box.currentText() == "W":
                c = 'w'

            im = self.image.astype(np.uint8)
            plt.imshow(im)
            plt.plot(self.track_e1[0],self.track_e1[1],color = c,linewidth=w)
            plt.plot(self.track_e2[0],self.track_e2[1],color = c,linewidth=w)
            plt.show()
        except Exception as e:
            error(e)
        
    def clear_pending_segment(self):
        """
        Clear any unsaved manual segment (used when overwriting).
        """
        if hasattr(self, "manuall_x"):
            del self.manuall_x
        if hasattr(self, "manuall_y"):
            del self.manuall_y
        if hasattr(self, "pending_mode"):
            del self.pending_mode

        # Clear the preview in the Qt widget too
        if hasattr(self, "manual_segment_screen"):
            from PyQt5.QtGui import QPixmap
            self.manual_segment_screen.setPixmap(QPixmap())

    def draw_segment(self, mode):
        from shapely.geometry import Polygon, MultiPolygon
        from shapely.ops import unary_union
        import matplotlib.pyplot as plt
        
        def draw_existing_cracks(im):
                """Overlay existing cracks (atomic + combined) in red onto a copy of the image."""
                H, W = im.shape[:2]
                ann = self.annotation.setdefault("annotations", {})
                atomic = ann.setdefault("atomic_cracks", {})
                combined = ann.setdefault("combined_cracks", {})

                def reconstruct_full_mask(crack):
                    mc, bb = crack.get("mask_crop"), crack.get("mask_bbox")
                    if mc is None or bb is None or not len(mc):
                        return np.zeros((H, W), np.uint8)
                    crop = np.array(mc, dtype=np.uint8)
                    x0, y0, w, h = [int(v) for v in bb]
                    x1, y1 = min(x0 + w, W), min(y0 + h, H)
                    mask = np.zeros((H, W), np.uint8)
                    mask[y0:y1, x0:x1] = crop[:y1 - y0, :x1 - x0]
                    return (mask > 0).astype(np.uint8)

                red = np.zeros_like(im)
                for crack in list(atomic.values()) + list(combined.values()):
                    m = reconstruct_full_mask(crack)
                    if np.any(m):
                        red[m.astype(bool)] = (255, 0, 0)

                return cv2.addWeighted(im, 1, red, 0.35, 0)

        print(mode)
        try:
            # --- Handle unsaved previous strokes ---
            if hasattr(self, "manuall_x") and len(getattr(self, "manuall_x", [])) > 0:
                from PyQt5.QtWidgets import QMessageBox
                msg = QMessageBox()
                msg.setIcon(QMessageBox.Warning)
                msg.setText("You already have an unsaved manual segment.\n"
                            "Continuing will overwrite it. Proceed?")
                msg.setWindowTitle("Overwrite Segment")
                msg.setStandardButtons(QMessageBox.Yes | QMessageBox.No)
                ret = msg.exec_()
                if ret == QMessageBox.No:
                    return
                else:
                    self.clear_pending_segment()

            image_size = self.select_image_size.value()
            x, y = ct.tools.Draw().counturs(
                self.image[:, :, ::-1],
                image_size,
                annotations=self.annotation.get("annotations", {}),
                mode=mode
            )
            if len(x) < 3:
                return  # not enough points

            coords = np.column_stack([x, y]).astype(np.int32)

            tol = 20       # closure distance in px
            min_gap = 10   # min separation in indices
            polys = []

            # --- Find ALL closures ---
            for i in range(len(coords) - min_gap):
                for j in range(i + min_gap, len(coords)):
                    d = np.linalg.norm(coords[i] - coords[j])
                    if d < tol:
                        loop_coords = coords[i:j+1]
                        if len(loop_coords) >= 3:
                            poly = Polygon(loop_coords)
                            if not poly.is_valid:
                                poly = poly.buffer(0)
                            if not poly.is_empty and poly.area > 30:
                                polys.append(poly)

            print(f"[DEBUG] Loops found: {len(polys)}")

            if not polys:
                print("[INFO] No closed loop detected in stroke.")
                return

            # --- Merge overlapping polygons ---
            merged = unary_union(polys)

            # always get a list of polygons back
            if isinstance(merged, Polygon):
                merged = [merged]
            elif isinstance(merged, MultiPolygon):
                merged = list(merged.geoms)

            print(f"[DEBUG] Independent loops after merge: {len(merged)}")

            # --- Convert back to OpenCV contours ---
            valid_loops = []
            for poly in merged:
                coords = np.array(poly.exterior.coords, dtype=np.int32).reshape((-1, 1, 2))
                valid_loops.append(coords)

            # save first loop coords for later use
            biggest = max(valid_loops, key=cv2.contourArea)
            self.manuall_x = biggest[:, 0, 0]
            self.manuall_y = biggest[:, 0, 1]
            self.pending_mode = mode
            
            # --- Preview ---
            H, W = self.image.shape[:2]
            im = self.image.astype(np.uint8).copy()
            
            im = draw_existing_cracks(im)

            preview_mask = np.zeros((H, W), np.uint8)
            cv2.fillPoly(preview_mask, valid_loops, 255)

            fill_color = (0, 255, 0) if mode == 'add' else (255, 50, 0)
            overlay = np.zeros_like(im)
            overlay[preview_mask > 0] = fill_color
            im = cv2.addWeighted(im, 1, overlay, 0.7, 0)

            # --- Show in Qt ---
            qimage = QImage(im, im.shape[1], im.shape[0],
                            im.strides[0], QImage.Format_RGB888)
            pixmap = QPixmap.fromImage(qimage)
            scaled = pixmap.scaled(
                self.manual_segment_screen.width(),
                self.manual_segment_screen.height(),
                Qt.KeepAspectRatio,
                Qt.FastTransformation
            )
            self.manual_segment_screen.setPixmap(scaled)

        except Exception as e:
            import traceback; traceback.print_exc()
            error(e)

    def erase_segment(self):
        """Convenience wrapper for erase mode."""
        return self.draw_segment('erase')
    
    def reset_canvas(self):
        """Clear pending manual segments and reset the preview canvas."""
        try:
            self.manuall_x = []
            self.manuall_y = []
            self.pending_mode = None

            im = self.image.astype(np.uint8).copy()
            im = self.draw_existing_cracks(im)  # <--- cracks back in

            qimage = QImage(im, im.shape[1], im.shape[0],
                            im.strides[0], QImage.Format_RGB888)
            pixmap = QPixmap.fromImage(qimage)
            scaled = pixmap.scaled(
                self.manual_segment_screen.width(),
                self.manual_segment_screen.height(),
                Qt.KeepAspectRatio,
                Qt.FastTransformation
            )
            self.manual_segment_screen.setPixmap(scaled)

            print("[INFO] Canvas reset complete.")
        except Exception as e:
            import traceback; traceback.print_exc()
            error(e)
                 
